import type { ColorTokens } from "@/types/pdf-themes";

/** Theme color token keys that can be used for the color prop */
export const THEME_COLOR_KEYS = [
  "foreground",
  "background",
  "muted",
  "mutedForeground",
  "primary",
  "primaryForeground",
  "border",
  "accent",
  "destructive",
  "success",
  "warning",
  "info",
] as const satisfies (keyof ColorTokens)[];

/** Resolves a color value: theme token key → hex, or raw CSS color as-is. */
export const resolveColor = (value: string, colors: ColorTokens): string => {
  const key = value as (typeof THEME_COLOR_KEYS)[number];
  return THEME_COLOR_KEYS.includes(key) ? colors[key] : value;
};

import {
  Component,
  InjectionToken,
  inject,
  input,
  signal,
} from "@angular/core";
import type { Signal } from "@angular/core";

import { professionalTheme } from "@/lib/pdf-themes/professional";
import type { PdfcnTheme } from "@/types/pdf-themes";

export type { PdfcnTheme };

export const PDFCN_THEME = new InjectionToken<Signal<PdfcnTheme>>(
  "PDFCN_THEME"
);

const defaultTheme = signal(professionalTheme).asReadonly();

/** The theme of the nearest `<pdf-theme-provider>`, or the professional theme. */
export const injectPdfcnTheme = (): Signal<PdfcnTheme> =>
  inject(PDFCN_THEME, { optional: true }) ?? defaultTheme;

/** Provides a theme to the components it wraps. */
@Component({
  providers: [
    {
      provide: PDFCN_THEME,
      useFactory: () => inject(PdfcnThemeProvider).theme,
    },
  ],
  selector: "pdf-theme-provider",
  template: "<ng-content />",
})
export class PdfcnThemeProvider {
  readonly theme = input(professionalTheme, {
    transform: (theme: PdfcnTheme | undefined) => theme ?? professionalTheme,
  });
}

import {
  DOCUMENT,
  ElementRef,
  RendererFactory2,
  createComponent,
  createEnvironmentInjector,
  inject,
  platformCore,
} from "@angular/core";
import type {
  EnvironmentInjector,
  Provider,
  Renderer2,
  Type,
} from "@angular/core";

/** An element in the tree an Angular component renders into. */
export class PdfElement {
  readonly name: string;
  readonly namespace: string | null;
  parent: PdfElement | null = null;
  readonly children: PdfNode[] = [];
  readonly attributes: Record<string, string> = {};
  /** The primitive directive on this element. Elements without one are transparent. */
  primitive: PdfPrimitive | null = null;

  constructor(name: string, namespace: string | null) {
    this.name = name;
    this.namespace = namespace;
  }
}

export class PdfTextNode {
  parent: PdfElement | null = null;

  value: string;

  constructor(value: string) {
    this.value = value;
  }
}

/** Angular's anchor for control flow and projection. Serializers skip it. */
export class PdfComment {
  parent: PdfElement | null = null;
}

export type PdfNode = PdfElement | PdfTextNode | PdfComment;

/** Base class for the directives that map to engine nodes. */
export abstract class PdfPrimitive {
  readonly element: PdfElement =
    inject<ElementRef<PdfElement>>(ElementRef).nativeElement;

  constructor() {
    this.element.primitive = this;
  }
}

const detach = (node: PdfNode) => {
  if (node.parent) {
    node.parent.children.splice(node.parent.children.indexOf(node), 1);
    node.parent = null;
  }
};

// oxlint-disable-next-line no-empty-function -- Renderer2 hooks the PDF tree ignores
const noop = () => {};

const renderer: Renderer2 = {
  addClass: noop,
  appendChild(parent: PdfElement, child: PdfNode) {
    detach(child);
    child.parent = parent;
    parent.children.push(child);
  },
  createComment: () => new PdfComment(),
  createElement: (name: string, namespace?: string | null) =>
    new PdfElement(name, namespace ?? null),
  createText: (value: string) => new PdfTextNode(value),
  data: {},
  destroy: noop,
  destroyNode: null,
  insertBefore(parent: PdfElement, child: PdfNode, ref: PdfNode | null) {
    detach(child);
    child.parent = parent;
    const index = ref ? parent.children.indexOf(ref) : -1;
    parent.children.splice(
      index === -1 ? parent.children.length : index,
      0,
      child
    );
  },
  listen: () => noop,
  nextSibling(node: PdfNode) {
    const siblings = node.parent?.children;
    return siblings?.[siblings.indexOf(node) + 1] ?? null;
  },
  parentNode: (node: PdfNode) => node.parent,
  removeAttribute(element: PdfElement, name: string) {
    Reflect.deleteProperty(element.attributes, name);
  },
  removeChild(_parent: PdfElement | null, child: PdfNode) {
    detach(child);
  },
  removeClass: noop,
  removeStyle: noop,
  selectRootElement: (node: PdfElement) => node,
  setAttribute(element: PdfElement, name: string, value: string) {
    element.attributes[name] = value;
  },
  setProperty: noop,
  setStyle: noop,
  setValue(node: PdfTextNode, value: string) {
    node.value = value;
  },
};

const rendererFactory: RendererFactory2 = {
  createRenderer: () => renderer,
};

export interface RenderOptions<T> {
  /** Values for the component's inputs. */
  inputs?: Partial<Record<keyof T & string, unknown>>;
  providers?: Provider[];
}

/** Renders a component once and reads its element tree before tearing it down. */
export const renderTree = <T, R>(
  component: Type<T>,
  { inputs = {}, providers = [] }: RenderOptions<T>,
  read: (root: PdfElement) => R
): R => {
  const environmentInjector = createEnvironmentInjector(
    [
      { provide: RendererFactory2, useValue: rendererFactory },
      // Angular looks up a style host on creation. PDF components have no styles.
      { provide: DOCUMENT, useValue: { head: null } },
      ...providers,
    ],
    platformCore().injector as EnvironmentInjector
  );
  const ref = createComponent(component, { environmentInjector });
  try {
    for (const [name, value] of Object.entries(inputs)) {
      ref.setInput(name, value);
    }
    ref.changeDetectorRef.detectChanges();
    return read(ref.location.nativeElement as PdfElement);
  } finally {
    ref.destroy();
    environmentInjector.destroy();
  }
};

/** Elements without a primitive pass their children through, like component hosts. */
export const contentOf = (element: PdfElement): (PdfElement | PdfTextNode)[] =>
  element.children.flatMap((child) => {
    if (child instanceof PdfComment) {
      return [];
    }
    if (child instanceof PdfElement && !child.primitive && !child.namespace) {
      return contentOf(child);
    }
    return [child];
  });

/** All text under a node, in document order. */
export const textOf = (node: PdfNode): string => {
  if (node instanceof PdfTextNode) {
    return node.value;
  }
  if (node instanceof PdfElement) {
    return node.children.map(textOf).join("");
  }
  return "";
};

import { Directive, booleanAttribute, input } from "@angular/core";

import { PdfPrimitive } from "@/lib/pdf-renderer";

/** CSS-like style object. Known CSS properties allow dot access. */
export type Style = Partial<Record<keyof CSSStyleDeclaration, unknown>> &
  Record<string, unknown>;

export const StyleSheet = {
  create<T extends Record<string, Style>>(styles: T): T {
    return styles;
  },
};

export type StyleInput = Style | Style[] | false | null | undefined;

/**
 * pdfcn's shared component tokens follow the PDF convention of using points.
 * Takumi follows browser CSS instead, where numeric lengths are pixels at
 * 96 DPI. Converting at the primitive boundary keeps the public component API
 * and the generated document's physical measurements aligned with Forme.
 */
export const PDF_POINT_TO_CSS_PIXEL = 96 / 72;

export const pointToCssPixel = (value: number): number =>
  value * PDF_POINT_TO_CSS_PIXEL;

const POINT_LENGTH_PROPERTIES = new Set([
  "blockSize",
  "borderBlockEndWidth",
  "borderBlockStartWidth",
  "borderBlockWidth",
  "borderBottomLeftRadius",
  "borderBottomRightRadius",
  "borderBottomWidth",
  "borderEndEndRadius",
  "borderEndStartRadius",
  "borderInlineEndWidth",
  "borderInlineStartWidth",
  "borderInlineWidth",
  "borderLeftWidth",
  "borderRadius",
  "borderRightWidth",
  "borderStartEndRadius",
  "borderStartStartRadius",
  "borderTopLeftRadius",
  "borderTopRightRadius",
  "borderTopWidth",
  "borderWidth",
  "bottom",
  "columnGap",
  "flexBasis",
  "fontSize",
  "gap",
  "height",
  "inlineSize",
  "inset",
  "insetBlock",
  "insetBlockEnd",
  "insetBlockStart",
  "insetInline",
  "insetInlineEnd",
  "insetInlineStart",
  "left",
  "letterSpacing",
  "margin",
  "marginBlock",
  "marginBlockEnd",
  "marginBlockStart",
  "marginBottom",
  "marginInline",
  "marginInlineEnd",
  "marginInlineStart",
  "marginLeft",
  "marginRight",
  "marginTop",
  "maxBlockSize",
  "maxHeight",
  "maxInlineSize",
  "maxWidth",
  "minBlockSize",
  "minHeight",
  "minInlineSize",
  "minWidth",
  "outlineOffset",
  "outlineWidth",
  "padding",
  "paddingBlock",
  "paddingBlockEnd",
  "paddingBlockStart",
  "paddingBottom",
  "paddingInline",
  "paddingInlineEnd",
  "paddingInlineStart",
  "paddingLeft",
  "paddingRight",
  "paddingTop",
  "right",
  "rowGap",
  "textDecorationThickness",
  "textIndent",
  "top",
  "width",
]);

export const normalizeTakumiStyle = (style: Style): Style => {
  const {
    marginHorizontal,
    marginVertical,
    paddingHorizontal,
    paddingVertical,
    ...normalized
  } = style;

  if (marginHorizontal !== undefined) {
    normalized.marginLeft ??= marginHorizontal;
    normalized.marginRight ??= marginHorizontal;
  }
  if (marginVertical !== undefined) {
    normalized.marginBottom ??= marginVertical;
    normalized.marginTop ??= marginVertical;
  }
  if (paddingHorizontal !== undefined) {
    normalized.paddingLeft ??= paddingHorizontal;
    normalized.paddingRight ??= paddingHorizontal;
  }
  if (paddingVertical !== undefined) {
    normalized.paddingBottom ??= paddingVertical;
    normalized.paddingTop ??= paddingVertical;
  }

  const borderSides = ["Top", "Right", "Bottom", "Left"] as const;
  if (normalized.borderWidth !== undefined) {
    normalized.borderStyle ??= "solid";
  }
  for (const side of borderSides) {
    if (normalized[`border${side}Width`] !== undefined) {
      normalized[`border${side}Style`] ??= "solid";
    }
  }

  return Object.fromEntries(
    Object.entries(normalized).map(([property, value]) => [
      property,
      typeof value === "number" && POINT_LENGTH_PROPERTIES.has(property)
        ? pointToCssPixel(value)
        : value,
    ])
  );
};

export const flatten = (
  style?: StyleInput
): Record<string, unknown> | undefined => {
  if (!style) {
    return undefined;
  }
  if (Array.isArray(style)) {
    return normalizeTakumiStyle(Object.assign({}, ...style.filter(Boolean)));
  }
  return normalizeTakumiStyle(style);
};

/** The tag and props a primitive stands for, as Takumi's element reader expects them. */
export interface TakumiHost {
  tag: string;
  props: {
    className?: string;
    height?: unknown;
    src?: unknown;
    style?: unknown;
    width?: unknown;
  } & Record<string, unknown>;
}

export abstract class TakumiPrimitive extends PdfPrimitive {
  abstract host(): TakumiHost;
}

@Directive({ selector: "takumi-view" })
export class TakumiView extends TakumiPrimitive {
  readonly style = input<StyleInput>();
  readonly className = input<string>();
  readonly wrap = input<boolean | undefined, unknown>(undefined, {
    transform: (value: unknown) =>
      value === undefined ? undefined : booleanAttribute(value),
  });
  readonly fixed = input(false, { transform: booleanAttribute });
  readonly break = input(false, { transform: booleanAttribute });

  host(): TakumiHost {
    const merged = {
      display: "flex",
      flexDirection: "column",
      ...flatten(this.style()),
    };
    if (this.break()) {
      Object.assign(merged, { breakBefore: "page" });
    }
    if (this.wrap() === false) {
      Object.assign(merged, { breakInside: "avoid" });
    }
    if (this.fixed()) {
      Object.assign(merged, { position: "fixed" });
    }
    return {
      props: { className: this.className(), style: merged },
      tag: "div",
    };
  }
}

/**
 * Text node. With `ifString`, it only wraps plain text content and
 * passes element content through unchanged.
 */
@Directive({ selector: "takumi-text" })
export class TakumiText extends TakumiPrimitive {
  readonly ifString = input(false, { transform: booleanAttribute });
  readonly style = input<StyleInput>();
  readonly className = input<string>();
  readonly href = input<string>();
  readonly src = input<string>();

  host(): TakumiHost {
    const merged = flatten(this.style());
    const link = this.href() ?? this.src();
    if (link) {
      return {
        props: { className: this.className(), href: link, style: merged },
        tag: "a",
      };
    }
    return {
      props: { className: this.className(), style: merged },
      tag: "span",
    };
  }
}

@Directive({ selector: "takumi-image" })
export class TakumiImage extends TakumiPrimitive {
  readonly src = input.required<string | { uri: string }>();
  readonly style = input<StyleInput>();

  host(): TakumiHost {
    const src = this.src();
    const resolved = typeof src === "string" ? src : src.uri;
    return {
      props: { alt: "", src: resolved, style: flatten(this.style()) },
      tag: "img",
    };
  }
}

@Directive({ selector: "takumi-link" })
export class TakumiLink extends TakumiPrimitive {
  readonly src = input.required<string>();
  readonly style = input<StyleInput>();

  host(): TakumiHost {
    return {
      props: { href: this.src(), style: flatten(this.style()) },
      tag: "a",
    };
  }
}

@Directive({ selector: "takumi-document" })
export class TakumiDocument extends TakumiPrimitive {
  readonly title = input<string>();
  readonly style = input<StyleInput>();

  host(): TakumiHost {
    return {
      props: {
        "data-pdf-document": this.title(),
        style: {
          display: "flex",
          flexDirection: "column",
          ...flatten(this.style()),
        },
      },
      tag: "div",
    };
  }
}

@Directive({ selector: "takumi-page" })
export class TakumiPage extends TakumiPrimitive {
  readonly size = input<string | { width: number; height: number }>();
  readonly style = input<StyleInput>();

  host(): TakumiHost {
    return {
      props: {
        "data-pdf-page": true,
        style: {
          display: "flex",
          flexDirection: "column",
          ...flatten(this.style()),
        },
      },
      tag: "div",
    };
  }
}

/** Takumi's page counters, which the engine fills in per page. */
@Directive({ selector: "takumi-counter" })
export class TakumiCounter extends TakumiPrimitive {
  readonly counter = input.required<"pageNumber" | "totalPages">();
  readonly format = input<string>();
  readonly className = input<string>();
  readonly style = input<Style>();

  host(): TakumiHost {
    return {
      props: {
        className: [this.counter(), this.format(), this.className()]
          .filter(Boolean)
          .join(" "),
        style: this.style(),
      },
      tag: "span",
    };
  }
}

/**
 * SVG graphic. Its children are plain `<svg:…>` elements; their attributes
 * are written into the markup in template order.
 */
@Directive({ selector: "takumi-svg" })
export class TakumiSvg extends TakumiPrimitive {
  readonly width = input<number | string>();
  readonly height = input<number | string>();
  readonly viewBox = input<string>();
  readonly style = input<Style>();

  host(): TakumiHost {
    const style = this.style();
    const height = this.height();
    const width = this.width();
    const numericHeight = typeof height === "number" ? height : undefined;
    const numericWidth = typeof width === "number" ? width : undefined;
    return {
      props: {
        height:
          numericHeight === undefined ? height : pointToCssPixel(numericHeight),
        style: style ? normalizeTakumiStyle(style) : undefined,
        viewBox:
          this.viewBox() ??
          (numericWidth !== undefined && numericHeight !== undefined
            ? `0 0 ${numericWidth} ${numericHeight}`
            : undefined),
        width:
          numericWidth === undefined ? width : pointToCssPixel(numericWidth),
      },
      tag: "svg",
    };
  }
}

export const TAKUMI_PRIMITIVES = [
  TakumiDocument,
  TakumiPage,
  TakumiView,
  TakumiText,
  TakumiImage,
  TakumiLink,
  TakumiCounter,
  TakumiSvg,
] as const;

import type { Type } from "@angular/core";
import { container, image, text } from "@takumi-rs/helpers";
import type { Node } from "@takumi-rs/helpers";

import {
  TakumiPrimitive,
  TakumiText,
} from "@/lib/pdf-primitives";
import type { TakumiHost } from "@/lib/pdf-primitives";
import {
  PdfElement,
  PdfTextNode,
  contentOf,
  renderTree,
} from "@/lib/pdf-renderer";
import type { PdfNode, RenderOptions } from "@/lib/pdf-renderer";

/** Takumi's default style for each tag this registry emits. */
const PRESETS: Record<string, Record<string, unknown>> = {
  div: { display: "block" },
};

const RESERVED = new Set([
  "children",
  "className",
  "class",
  "id",
  "style",
  "tw",
]);

const SVG_KEBAB = new Set([
  "clipPath",
  "clipRule",
  "fillOpacity",
  "fillRule",
  "fontFamily",
  "fontSize",
  "fontStyle",
  "fontWeight",
  "stopColor",
  "stopOpacity",
  "strokeDasharray",
  "strokeDashoffset",
  "strokeLinecap",
  "strokeLinejoin",
  "strokeMiterlimit",
  "strokeOpacity",
  "strokeWidth",
  "textAnchor",
]);

const kebab = (name: string) =>
  name.replaceAll(/([A-Z])/g, "-$1").toLowerCase();

const escape = (value: string) =>
  value
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");

/** Primitive props become string attributes, as Takumi's element reader does. */
const attributesOf = (props: Record<string, unknown>) => {
  let attributes: Record<string, string> | undefined;
  for (const [name, value] of Object.entries(props)) {
    if (
      RESERVED.has(name) ||
      value === null ||
      value === undefined ||
      value === false ||
      typeof value === "object" ||
      typeof value === "function"
    ) {
      continue;
    }
    attributes ??= {};
    attributes[name] = value === true ? "" : String(value);
  }
  return attributes;
};

const describe = ({ tag, props }: TakumiHost) => {
  const style =
    props.style &&
    typeof props.style === "object" &&
    Object.keys(props.style).length > 0
      ? (props.style as Record<string, unknown>)
      : undefined;
  return {
    attributes: attributesOf(props),
    className: props.className as string | undefined,
    preset: PRESETS[tag],
    style,
    tagName: tag,
  };
};

const svgAttribute = (name: string, value: unknown) => {
  if (value === null || value === undefined) {
    return "";
  }
  if (name === "style" && typeof value === "object") {
    const css = Object.entries(value)
      .map(([key, entry]) => `${kebab(key)}:${String(entry).trim()}`)
      .join(";");
    return css ? ` style="${escape(css)}"` : "";
  }
  let attribute = SVG_KEBAB.has(name) ? kebab(name) : name;
  if (name === "className") {
    attribute = "class";
  }
  return ` ${attribute}="${escape(String(value))}"`;
};

const svgChild = (node: PdfNode): string => {
  if (node instanceof PdfTextNode) {
    return node.value;
  }
  if (!(node instanceof PdfElement)) {
    return "";
  }
  const attributes = Object.entries(node.attributes)
    .map(([name, value]) => svgAttribute(name, value))
    .join("");
  return `<${node.name}${attributes}>${node.children.map(svgChild).join("")}</${node.name}>`;
};

const svgMarkup = (props: Record<string, unknown>, element: PdfElement) => {
  const attributes = Object.entries(props)
    .map(([name, value]) => svgAttribute(name, value))
    .join("");
  const xmlns = "xmlns" in props ? "" : ` xmlns="http://www.w3.org/2000/svg"`;
  return `<svg${attributes}${xmlns}>${element.children.map(svgChild).join("")}</svg>`;
};

const toNumber = (value: unknown) =>
  value === undefined ? undefined : Number(value);

const serializeChildren = (element: PdfElement): Node[] =>
  contentOf(element).flatMap((child) =>
    child instanceof PdfTextNode
      ? [text({ text: child.value })]
      : // oxlint-disable-next-line no-use-before-define -- mutual recursion
        serializeElement(child)
  );

const serializeElement = (element: PdfElement): Node[] => {
  const { primitive } = element;
  if (!(primitive instanceof TakumiPrimitive)) {
    return [];
  }
  const content = contentOf(element);
  const textOnly =
    content.length > 0 &&
    content.every((child) => child instanceof PdfTextNode);
  if (primitive instanceof TakumiText && primitive.ifString() && !textOnly) {
    return serializeChildren(element);
  }
  const host = primitive.host();
  const description = describe(host);

  if (host.tag === "img") {
    return [
      image({
        height: toNumber(host.props.height),
        src: host.props.src as string,
        width: toNumber(host.props.width),
        ...description,
      }),
    ];
  }
  if (host.tag === "svg") {
    return [
      image({
        height: toNumber(host.props.height),
        src: svgMarkup(host.props, element),
        width: toNumber(host.props.width),
        ...description,
      }),
    ];
  }

  if (textOnly) {
    return [
      text({
        text: content.map((child) => child.value).join(""),
        ...description,
      }),
    ];
  }
  return [container({ children: serializeChildren(element), ...description })];
};

const serializeRoot = (root: PdfElement) => {
  const nodes = serializeChildren(root);
  if (nodes.length !== 1) {
    throw new Error("The component must render exactly one root element.");
  }
  return { node: nodes[0], stylesheets: [] as string[] };
};

/** Renders an Angular component built from Takumi primitives to a Takumi node. */
export const renderTakumiDocument = <T>(
  component: Type<T>,
  options: RenderOptions<T> = {}
) => renderTree(component, options, serializeRoot);
